    d2 = int(input())
    for d, e in [(d1, d2), (d2, d1)]:
        if r1 == d and r2 == d:
            print(f"x = {d}: hole at ({d}, 0)")
        elif r1 == d:
            print(f"x = {d}: hole at ({d}, {Fraction(d - r2, d - e)})")
        elif r2 == d:
            print(f"x = {d}: hole at ({d}, {Fraction(d - r1, d - e)})")
        else:
            print(f"x = {d}: vertical asymptote")

