from fractions import Fraction

def sign(v):
    if v > 0:
        return "positive"
    return "negative"

cases = [
    ("a full sketch", lambda x: (2 * x ** 2 - 2) / (x ** 2 - 4), [-2, -1, 1, 2]),
    ("a line over a line", lambda x: (2 * x + 1) / (x - 3), [Fraction(-1, 2), 3]),
    ("a constant top", lambda x: 4 / (x + 2), [-2]),
    ("no y-intercept", lambda x: (x - 4) / (2 * x), [0, 4]),
]
for label, f, breaks in cases:
    listed = ""
    for b in breaks:
        listed = listed + f" {b}"
    print(f"{label}: break points{listed}")
    tests = [breaks[0] - 1]
    for i in range(len(breaks) - 1):
        tests.append(Fraction(breaks[i] + breaks[i + 1], 2))
    tests.append(breaks[len(breaks) - 1] + 1)
    for t in tests:
        print(f"  test x = {t}: f = {Fraction(f(Fraction(t)))}, {sign(f(Fraction(t)))}")

