from fractions import Fraction

n = int(input())
for i in range(n):
    a = int(input())
    b = int(input())
    c = int(input())
    d = int(input())
    if a * d - b * c == 0:
        print(f"constant y = {Fraction(a, c)} with a hole at x = {Fraction(-d, c)}")
    else:
        print(f"vertical asymptote: x = {Fraction(-d, c)}")
        print(f"horizontal asymptote: y = {Fraction(a, c)}")
        if a == 0:
            print("x-intercept: none")
        else:
            print(f"x-intercept: {Fraction(-b, a)}")
        if d == 0:
            print("y-intercept: none")
        else:
            print(f"y-intercept: {Fraction(b, d)}")
